import { expect, expectStatus, test } from "../../fixtures";

const KINDS = ["w9", "insurance_certificate", "contract"] as const;

test.describe("REV-01 submit vendor for review", () => {
  test(
    "submitting a draft vendor with all documents extracted moves it to in_review and records an audit event",
    { tag: "@REV-01" },
    async ({ apiAs }) => {
      // Arrange: a member creates a draft vendor with a unique name and email.
      const member = await apiAs("member");
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      const created = await member.post("/api/vendors", {
        data: {
          name: `REV01 Vendor ${suffix}`,
          category: "services",
          contact_email: `rev01+${suffix}@vendor.test`,
        },
      });
      const vendor = await expectStatus<{ id: string; status: string }>(created, 201);
      expect(vendor.status).toBe("draft");

      // Arrange: upload one document of each required kind.
      for (const kind of KINDS) {
        const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind,
            file: {
              name: `${kind}-${suffix}.pdf`,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4 ${kind} ${suffix}`),
            },
          },
        });
        await expectStatus(upload, 201);
      }

      // Arrange: wait until every document has been extracted.
      const documents = await expectStatus<Array<{ id: string; kind: string; status: string }>>(
        await member.get(`/api/vendors/${vendor.id}/documents`),
        200,
      );
      expect(documents.map((d) => d.kind).sort()).toEqual([...KINDS].sort());

      for (const document of documents) {
        await expect
          .poll(
            async () =>
              (await expectStatus<{ status: string }>(await member.get(`/api/documents/${document.id}`), 200)).status,
            { timeout: 60_000, intervals: [500, 1000, 2000] },
          )
          .toBe("extracted");
      }

      // Act: submit the vendor for review.
      const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Assert: response status and vendor status.
      const body = await expectStatus<{ id: string; status: string; submitted_at: string | null }>(submitted, 200);
      expect(body.id).toBe(vendor.id);
      expect(body.status).toBe("in_review");
      expect(body.submitted_at).not.toBeNull();

      // Assert: audit trail records the submission.
      const audit = await expectStatus<{ items: Array<{ action: string }> }>(
        await member.get(`/api/vendors/${vendor.id}/audit`),
        200,
      );
      expect(audit.items.some((event) => event.action === "vendor.submitted")).toBe(true);
    },
  );
});
